export function add(a, b) {
    return a + b;
}

export function multiply(a, b) {
    return a * b;
}

// Self-check
if (add(2, 2) !== 4) {
    throw new Error("Self-check failed: add(2, 2) should equal 4");
}

import { add, multiply } from './maths.js';

console.log('Testing add function:');
console.log('add(2, 3) =', add(2, 3));
console.log('add(5, 7) =', add(5, 7));

console.log('Testing multiply function:');
console.log('multiply(2, 3) =', multiply(2, 3));
console.log('multiply(5, 7) =', multiply(5, 7));

// Verify the functions work as expected
if (add(2, 3) === 5 && multiply(2, 3) === 6) {
    console.log('All tests passed!');
} else {
    console.log('Some tests failed!');
}

